<template>
  <div class="lottery-container">
    <h2>🎉 幸运转盘</h2>
    <el-button type="success" @click="spin">开始抽奖</el-button>
    <p v-if="result">{{ result }}</p>
  </div>
</template>

<script>
export default {
  data() {
    return {
      result: ''
    }
  },
  methods: {
    spin() {
      // 将奖品选项改为胖猫和四种麦当劳食品
      const prizes = ['胖猫', '麦当劳薯条', '麦当劳汉堡', '麦当劳冰淇淋', '麦当劳可乐']
      const index = Math.floor(Math.random() * prizes.length)
      this.result = `你抽中了：${prizes[index]}！`
    }
  }
}
</script>

<style scoped>
.lottery-container {
  text-align: center;
  margin-top: 100px;
  font-size: 20px;
}
</style>
